#include "test_runner.h"

TEST(init_state) {
  seq_init();
  ASSERT_EQ(seq_count(), 0);
  ASSERT_EQ(seq_current_led(), -1);
  ASSERT_PIN(7, LOW);
  ASSERT_PIN(6, LOW);
  ASSERT_PIN(5, LOW);
  ASSERT_PIN(4, LOW);
}

TEST(apply_valid_step) {
  seq_init();
  ASSERT_TRUE(seq_apply(2));
  ASSERT_PIN(5, HIGH);
  ASSERT_EQ(seq_current_led(), 2);
  ASSERT_TRUE(seq_apply(3));
  ASSERT_PIN(5, LOW);
  ASSERT_PIN(4, HIGH);
  ASSERT_EQ(seq_current_led(), 3);
}

TEST(apply_invalid_step) {
  seq_init();
  ASSERT_FALSE(seq_apply(4));
  ASSERT_FALSE(seq_apply(255));
}

TEST(advance_cycles_through_leds) {
  seq_init();
  seq_advance();
  ASSERT_PIN(7, HIGH);
  ASSERT_EQ(seq_count(), 1);
  seq_advance();
  ASSERT_PIN(7, LOW);
  ASSERT_PIN(6, HIGH);
  ASSERT_EQ(seq_count(), 2);
  seq_advance();
  ASSERT_PIN(6, LOW);
  ASSERT_PIN(5, HIGH);
  ASSERT_EQ(seq_count(), 3);
  seq_advance();
  ASSERT_PIN(5, LOW);
  ASSERT_PIN(4, HIGH);
  ASSERT_EQ(seq_count(), 0);
  seq_advance();
  ASSERT_PIN(4, LOW);
  ASSERT_PIN(7, HIGH);
  ASSERT_EQ(seq_count(), 1);
}

